def clean(value):
 if isinstance(value,str):
  for old,new in sorted(words.items(),key=lambda x:-len(x[0])):value=value.replace(old,new)
  return value
 if isinstance(value,list):return [clean(v) for v in value]
 if isinstance(value,dict):return {k:(v if k in ['id','document_id','sha256','topic','day','author_id','question_type','answer_format','status','verification','taxonomy_status'] else clean(v)) for k,v in value.items()}
 return value
